clc;
clear all;
close all;

t=0:0.01:10;

% Fourier Series coefficients
x = 3 + cos(pi*t)+ 4*cos(2*pi*t) ;

% Magnitude spectrum
mag = abs(x);

% Phase spectrum
phase = angle(x);

% Frequency axis for Fourier transform
freq = -3:0.01:3;   % adjust range as needed

% Fourier transform using numerical integration
Xf = zeros(size(freq));

for k = 1:length(freq)
    Xf(k) = trapz(t, x .* exp(-1j*2*pi*freq(k)*t));
end

% Plot magnitude and phase spectra
figure; %[output:683b5924]
subplot(3,1,1); %[output:683b5924]
plot(t, x, 'b', 'LineWidth', 1.5); %[output:683b5924]
xlabel('Time (s)'); %[output:683b5924]
ylabel('x(t)'); %[output:683b5924]
title('Original Signal'); %[output:683b5924]
grid on; %[output:683b5924]

subplot(3,1,2); %[output:683b5924]
plot(freq, abs(Xf), 'LineWidth', 1.5); %[output:683b5924]
xlabel('Frequency (Hz)'); %[output:683b5924]
ylabel('Magnitude'); %[output:683b5924]
title('Magnitude Spectrum using trapz'); %[output:683b5924]
grid on; %[output:683b5924]


subplot(3,1,3); %[output:683b5924]
plot(freq, angle(Xf), 'LineWidth', 1.5); %[output:683b5924]
xlabel('Frequency (Hz)'); %[output:683b5924]
ylabel('Phase (rad)'); %[output:683b5924]
title('Phase Spectrum using trapz'); %[output:683b5924]
grid on; %[output:683b5924]



